SELECT 'function ' || q.name || '(' || q.identity_arguments || ')' AS key,
       encode(sha256(convert_to(regexp_replace(
           (to_jsonb(q) - 'owner' - 'acl' - 'schema')::text,
           '\m' || current_schema() || '\M', '__SCHEMA__', 'g'), 'UTF8')), 'hex') AS digest
  FROM (
        SELECT n.nspname AS schema, p.proname AS name,
               pg_get_function_identity_arguments(p.oid) AS identity_arguments,
               pg_get_function_arguments(p.oid) AS arguments,
               pg_get_function_result(p.oid) AS result,
               p.prokind::text AS kind,
               l.lanname AS language,
               p.prosrc AS source,
               pg_get_function_sqlbody(p.oid) AS sql_body,
               p.probin AS binary,
               p.prosecdef AS security_definer,
               p.proleakproof AS leakproof,
               p.proisstrict AS strict,
               p.proretset AS returns_set,
               p.provolatile::text AS volatility,
               p.proparallel::text AS parallel,
               p.procost::text AS cost, p.prorows::text AS rows,
               CASE WHEN p.prosupport <> 0 THEN p.prosupport::regproc::text END AS support,
               p.proconfig AS config,
               CASE WHEN p.prokind <> 'a' THEN pg_get_functiondef(p.oid) END AS definition,
               pg_get_userbyid(p.proowner) AS owner,
               (SELECT coalesce(jsonb_agg(jsonb_build_array(
            CASE WHEN x.grantee = 0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,
            x.privilege_type, x.is_grantable, pg_get_userbyid(x.grantor))), '[]'::jsonb)
          FROM aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) x) AS acl,
               obj_description(p.oid, 'pg_proc') AS comment
          FROM pg_proc p
          JOIN pg_namespace n ON n.oid = p.pronamespace
          JOIN pg_language l ON l.oid = p.prolang
         WHERE (n.nspname <> 'information_schema' AND n.nspname !~ '^pg_') AND NOT EXISTS (SELECT 1 FROM pg_depend e
            WHERE e.classid = 'pg_proc'::regclass AND e.objid = p.oid
              AND e.objsubid = 0 AND e.deptype = 'e')) q
 WHERE q.schema = current_schema()
